const rotateOAuthGrant = `-- name: RotateOAuthGrant :execrows
UPDATE oauth_grants
SET prev_refresh_token_hash = refresh_token_hash, refresh_token_hash = ?, rotated_at = ?, last_used_at = ?, expires_at = ?
WHERE id = ? AND refresh_token_hash = ? AND revoked_at IS NULL
`

type RotateOAuthGrantParams struct {
	RefreshTokenHash   string
	RotatedAt          *types.DateTime
	LastUsedAt         types.DateTime
	ExpiresAt          types.DateTime
	ID                 string
	RefreshTokenHash_2 string
}

// Conditional on the hash being rotated away, so of two concurrent refreshes
// presenting the same token exactly one rotates.
func (q *Queries) RotateOAuthGrant(ctx context.Context, arg RotateOAuthGrantParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, rotateOAuthGrant,
		arg.RefreshTokenHash,
		arg.RotatedAt,
		arg.LastUsedAt,
		arg.ExpiresAt,
		arg.ID,
		arg.RefreshTokenHash_2,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const signInEmailInUse = `-- name: SignInEmailInUse :one
SELECT EXISTS (
    SELECT 1 FROM user_credentials c WHERE c.email = ?1
    UNION ALL
    SELECT 1 FROM user_connected_accounts a WHERE a.provider <> 'local' AND a.email = ?1
)
`

// Whether an account already answers to this address: a password
// account's email, or the email a linked provider vouched for.
func (q *Queries) SignInEmailInUse(ctx context.Context, address string) (bool, error) {
	row := q.db.QueryRowContext(ctx, signInEmailInUse, address)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

const updateIdentityEmail = `-- name: UpdateIdentityEmail :execrows
UPDATE user_connected_accounts SET email = ? WHERE provider = ? AND external_id = ?
`

type UpdateIdentityEmailParams struct {
	Email      *string
	Provider   string
	ExternalID string
}

func (q *Queries) UpdateIdentityEmail(ctx context.Context, arg UpdateIdentityEmailParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateIdentityEmail, arg.Email, arg.Provider, arg.ExternalID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const userHasPassword = `-- name: UserHasPassword :one
SELECT EXISTS (SELECT 1 FROM user_credentials WHERE user_id = ?)
`

func (q *Queries) UserHasPassword(ctx context.Context, userID string) (bool, error) {
	row := q.db.QueryRowContext(ctx, userHasPassword, userID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}
